{
  "findings": [
    {
      "check_id": "CKV_AZURE_35",
      "title": "Storage account is not enforcing HTTPS",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "HIGH",
      "explanation": "The storage account is not configured to enable HTTPS traffic only, allowing unencrypted HTTP traffic."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"LRS\"\n  enable_https_traffic_only = true\n}",
  "fix_summary": "Enabled HTTPS traffic only for the storage account to prevent unencrypted data transmission."
}
